const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;padding:10px;color:var(--ink);background:transparent;font:13px/1.35 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;overflow:hidden}\n.card[data-size=\"3x3\"]{padding:8px}\n.card *{box-sizing:border-box}\n.app{height:100%;min-height:0;min-width:0;display:flex;flex-direction:column}\nbutton{font:inherit;color:inherit}\n\n/* \u6309\u94ae */\n.btn{min-height:32px;padding:0 12px;border-radius:8px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);cursor:pointer;white-space:nowrap}\n.btn.sm{min-height:28px;padding:0 9px;font-size:12px}\n.btn.pri{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.btn.danger{color:#B4533A;border-color:#B4533A;font-weight:600}\n.btn:focus-visible,.tab:focus-visible,.row:focus-visible,.tog:focus-visible,.x:focus-visible,.in:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n/* \u5217\u8868\u9875\u9aa8\u67b6 */\n.lv{flex:1;min-height:0;min-width:0;display:grid;gap:6px 8px;grid-template-columns:minmax(0,1fr) auto;grid-template-rows:auto minmax(0,1fr);grid-template-areas:\"stats add\" \"main main\"}\n.stats{grid-area:stats;min-width:0;display:flex;gap:12px;align-items:flex-end}\n.addbtn{grid-area:add;align-self:center}\n.main{grid-area:main;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n.card[data-size=\"6x3\"] .lv{grid-template-columns:112px minmax(0,1fr);grid-template-rows:minmax(0,1fr) auto;grid-template-areas:\"stats main\" \"add main\";gap:8px 10px}\n.card[data-size=\"3x6\"] .lv,.card[data-size=\"6x6\"] .lv{grid-template-columns:minmax(0,1fr);grid-template-rows:auto minmax(0,1fr) auto;grid-template-areas:\"stats\" \"main\" \"add\";gap:8px}\n.card[data-size=\"6x3\"] .addbtn,.card[data-size=\"3x6\"] .addbtn,.card[data-size=\"6x6\"] .addbtn{align-self:stretch;width:100%}\n\n/* \u6c47\u603b */\n.stat{min-width:0}\n.stat .k{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.stat .v{font-size:15px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.stat.hot .v,.stat.hot .k{color:#B4533A}\n.stat.hot .k{font-weight:600}\n.card[data-size=\"3x3\"] .s-soon,.card[data-size=\"3x3\"] .s-paid,.card[data-size=\"6x3\"] .s-paid,.card[data-size=\"3x6\"] .s-paid{display:none}\n.card[data-size=\"6x3\"] .stats{flex-direction:column;align-items:stretch;gap:7px;justify-content:center}\n.card[data-size=\"3x6\"] .stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}\n.card[data-size=\"3x6\"] .s-out{grid-column:1 / -1}\n.card[data-size=\"6x6\"] .stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}\n.card[data-size=\"3x6\"] .stat,.card[data-size=\"6x6\"] .stat{padding:6px 8px;background:var(--panel-paper);border:1px solid var(--line);border-radius:8px}\n.card[data-size=\"6x6\"] .stat .v{font-size:16px}\n.card[data-size=\"3x6\"] .s-out .v{font-size:18px}\n\n/* \u7b5b\u9009 */\n.tabs{flex:none;display:flex;gap:4px;min-width:0}\n.tab{flex:1 1 0;min-width:0;min-height:24px;padding:0 4px;border-radius:12px;border:1px solid var(--line);background:var(--soft);color:var(--ink);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;cursor:pointer}\n.tab.on{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.card[data-size=\"3x6\"] .tab,.card[data-size=\"6x6\"] .tab{min-height:28px;font-size:12px}\n\n/* \u5217\u8868 */\n.list{flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:6px;padding-right:2px}\n.empty{padding:14px 6px;text-align:center;color:var(--muted);font-size:12px}\n.empty.sm{padding:8px 0;text-align:left}\n.row{flex:none;width:100%;text-align:left;cursor:pointer;display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-areas:\"t am\" \"ds pg\" \"bar bar\";gap:2px 8px;padding:7px 9px;border:1px solid var(--line);border-left:3px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink)}\n.row.st-overdue{border-left-color:#B4533A}\n.row.st-soon{border-left-color:var(--accent)}\n.row.st-paid{opacity:.8}\n.row .t{grid-area:t;min-width:0}\n.row .cl,.row .pj{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.row .cl{font-weight:600;display:block}\n.row .pj{display:block;color:var(--muted);font-size:12px}\n.row .am{grid-area:am;font-weight:700;white-space:nowrap;text-align:right}\n.row .lbl{font-weight:400;font-size:11px;color:var(--muted)}\n.row .ds{grid-area:ds;min-width:0;display:flex;align-items:center;gap:6px;white-space:nowrap;overflow:hidden}\n.row .due{font-size:12px;color:var(--muted)}\n.row.st-overdue .due{color:#B4533A;font-weight:600}\n.row.st-soon .due{color:var(--accent);font-weight:600}\n.row .pg{grid-area:pg;font-size:11px;color:var(--muted);white-space:nowrap;text-align:right}\n.row .bar{grid-area:bar;margin-top:3px}\n.inv{flex:none;font-size:10.5px;line-height:16px;padding:0 6px;border-radius:9px;border:1px solid var(--line);color:var(--muted)}\n.inv.yes{border-color:var(--accent);background:var(--soft);color:var(--ink)}\n.bar{display:block;height:4px;border-radius:2px;background:var(--line);overflow:hidden}\n.bar i{display:block;height:100%;background:var(--accent);border-radius:2px}\n.bar.big{height:6px;border-radius:3px;flex:none}\n.card[data-size=\"3x3\"] .row{padding:5px 7px;grid-template-areas:\"t am\" \"ds ds\" \"bar bar\";gap:1px 6px}\n.card[data-size=\"3x3\"] .row .pg,.card[data-size=\"3x3\"] .row .lbl{display:none}\n.card[data-size=\"3x3\"] .row .cl,.card[data-size=\"3x3\"] .row .pj{display:inline}\n.card[data-size=\"3x3\"] .row .t{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.card[data-size=\"3x3\"] .row .pj{margin-left:4px;font-size:11px}\n.card[data-size=\"3x3\"] .row .bar{height:3px;margin-top:2px}\n.card[data-size=\"6x3\"] .row{padding:5px 9px}\n.card[data-size=\"6x3\"] .row .t{display:flex;gap:6px;align-items:baseline}\n.card[data-size=\"6x3\"] .row .cl{flex:0 1 auto}\n.card[data-size=\"6x3\"] .row .pj{flex:1 1 0}\n\n\n/* \u8be6\u60c5 / \u8868\u5355 */\n.panel{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:8px}\n.ph{flex:none;display:flex;align-items:center;gap:6px;min-width:0}\n.ph h2{flex:1;min-width:0;margin:0;font-size:14px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.pb{flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:10px;padding-right:2px}\n.pf{flex:none;display:flex;flex-direction:column;gap:6px}\n.err{flex:none;padding:6px 8px;border-radius:8px;border:1px solid #B4533A;color:#B4533A;font-size:12px;font-weight:600;background:var(--panel-paper)}\n.proj{color:var(--muted);font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:none}\n.dstat{flex:none;font-weight:700;font-size:13px}\n.dstat .dd{font-weight:400;font-size:12px;color:var(--muted)}\n.dstat.st-overdue{color:#B4533A}\n.dstat.st-soon{color:var(--accent)}\n.sum{flex:none;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}\n.sc{min-width:0;padding:5px 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);display:flex;flex-direction:column}\n.sc .k{font-size:11px;color:var(--muted);white-space:nowrap}\n.sc .v{font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.sc.hot .v{color:#B4533A}\n.card[data-size=\"3x3\"] .sum,.card[data-size=\"3x6\"] .sum{grid-template-columns:minmax(0,1fr);gap:3px}\n.card[data-size=\"3x3\"] .sc,.card[data-size=\"3x6\"] .sc{flex-direction:row;justify-content:space-between;align-items:baseline;padding:3px 8px;gap:8px}\n.done{flex:none;padding:8px;border-radius:8px;background:var(--soft);font-weight:600}\n.sec{flex:none;display:flex;flex-direction:column;gap:6px}\n.sh{font-size:12px;font-weight:700;color:var(--muted)}\n.pform{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:6px}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0}\n.fl{font-size:11px;color:var(--muted)}\n.fl em{font-style:normal;color:var(--accent);margin-left:2px}\n.in{width:100%;min-width:0;min-height:34px;padding:4px 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font:inherit;font-size:13px}\n.in::placeholder{color:var(--muted)}\n.acts{display:flex;flex-wrap:wrap;gap:6px;justify-content:flex-end}\n.acts .btn.pri{flex:1 1 90px}\n.hint{font-size:11px;color:var(--muted)}\n.invrow{flex:none;display:flex;align-items:center;gap:8px;flex-wrap:wrap}\n.tog{min-height:30px;padding:0 10px;border-radius:15px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);cursor:pointer;font-size:12px;white-space:nowrap}\n.tog.on{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.pay{display:flex;align-items:center;gap:8px;padding:4px 0;border-bottom:1px solid var(--line);min-width:0}\n.pay .pd{flex:none;color:var(--muted);font-size:12px;white-space:nowrap}\n.pay .pa{flex:1;min-width:0;text-align:right;font-weight:700;white-space:nowrap}\n.x{flex:none;width:28px;height:28px;border-radius:14px;border:1px solid var(--line);background:transparent;color:var(--muted);cursor:pointer;font-size:16px;line-height:1}\n.card[data-size=\"3x3\"] .ph h2{font-size:13px}\n.card[data-size=\"3x3\"] .btn.sm{padding:0 7px}\n";
var DAYMS=86400000;
var RANK={overdue:0,soon:1,later:2,paid:3};
function r2(x){return Math.round((+x||0)*100)/100;}
function pday(s){var m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(s||'');return m?Date.UTC(+m[1],+m[2]-1,+m[3]):NaN;}
function validDate(s){var t=pday(s);return !isNaN(t)&&t>=pday('2000-01-01')&&t<=pday('2099-12-31');}
function dayDiff(a,b){return Math.round((pday(a)-pday(b))/DAYMS);}
function listOf(s){return Array.isArray(s&&s.items)?s.items:[];}
function mapItem(s,id,fn){return Object.assign({},s,{items:listOf(s).map(function(x){return x.id===id?fn(x):x;})});}
function byDate(a,b){return a.date<b.date?-1:a.date>b.date?1:0;}
function parseAmt(v){var n=Number(String(v==null?'':v).trim());return Number.isFinite(n)&&n>0&&n<1e10?r2(n):NaN;}

/* 人民币；lim 为正数时，达到该数额改用「万」缩写 */
function money(n,lim){
  n=r2(n);var neg=n<0;n=Math.abs(n);var t;
  if(lim&&n>=lim){
    var w=n/10000;
    t=(w>=100?String(Math.round(w)):String(Math.round(w*10)/10))+'万';
  }else{
    var p=n.toFixed(2).split('.');
    t=p[0].replace(/\B(?=(\d{3})+(?!\d))/g,',')+(p[1]==='00'?'':'.'+p[1]);
  }
  return (neg?'-':'')+'¥'+t;
}

function showDate(d,today){
  var m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(d||'');
  if(!m)return '';
  var md=(+m[2])+'月'+(+m[3])+'日';
  return today&&String(today).slice(0,4)===m[1]?md:m[1]+'年'+md;
}

/* st: overdue 逾期未收齐 / soon 7天内到期（含今天）/ later 之后 / paid 已收齐 */
function calc(it,today){
  var paid=r2((it.payments||[]).reduce(function(a,p){return a+(+p.amount||0);},0));
  var amount=r2(it.amount);
  var out=r2(amount-paid);
  var days=dayDiff(it.due,today);
  var st=out<=0?'paid':days<0?'overdue':days<=7?'soon':'later';
  return {paid:paid,amount:amount,out:out,days:days,st:st,pct:amount>0?Math.max(0,Math.min(100,paid/amount*100)):0};
}

function dueText(it,c,today){
  if(c.st==='paid')return '已收齐';
  if(c.st==='overdue')return '逾期 '+(-c.days)+' 天';
  if(c.days===0)return '今天到期';
  if(c.st==='soon')return c.days+' 天后到期';
  return showDate(it.due,today)+'到期';
}

/* 逾期（越久越靠前）→ 7天内 → 之后 → 已收齐 */
function sortItems(items,today){
  return items.map(function(it){return {it:it,c:calc(it,today)};}).sort(function(a,b){
    var ra=RANK[a.c.st],rb=RANK[b.c.st];
    if(ra!==rb)return ra-rb;
    var da=pday(a.it.due)||0,db=pday(b.it.due)||0;
    if(a.c.st==='paid')return db-da;
    return (da-db)||String(a.it.client).localeCompare(String(b.it.client),'zh');
  });
}


function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,size}=ctx;
  const today=day();
  const items=listOf(state);
  if(!ui.view)ui.view='list';
  if(!ui.filter)ui.filter='all';

  function h(tag,attrs){
    const out=[];
    function push(c){
      if(c==null||c===false)return;
      if(Array.isArray(c)){c.forEach(push);return;}
      out.push(typeof c==='number'?String(c):c);
    }
    for(let i=2;i<arguments.length;i++)push(arguments[i]);
    return el.apply(null,[tag,attrs||{}].concat(out));
  }
  const nu=p=>Object.assign({},ui,{err:'',busy:false,delPay:null,delItem:false},p);
  const fail=()=>{ui.busy=false;ui.err='保存失败，数据没有改动，请稍后再试';redraw();};
  const warn=msg=>{ui.err=msg;redraw();};
  const errBox=()=>ui.err?h('div',{class:'err',role:'alert'},'⚠ '+ui.err):null;
  const btn=(cls,label,onclick,extra)=>h('button',Object.assign({type:'button',class:'btn '+cls,onclick:onclick},extra||{}),label);

  /* ---------- 列表 ---------- */
  function rowEl(r){
    const it=r.it,c=r.c;
    const bar=h('span',{class:'bar'});
    const fill=h('i');
    fill.style.width=c.pct+'%';
    bar.appendChild(fill);
    return h('button',{type:'button',class:'row st-'+c.st,onclick:()=>{
        ui.sel=it.id;ui.view='detail';ui.pay=null;ui.err='';ui.delPay=null;ui.delItem=false;redraw();
      }},
      h('span',{class:'t'},h('b',{class:'cl'},it.client),it.project?h('span',{class:'pj'},it.project):null),
      h('span',{class:'am'},c.st==='paid'?'已收齐':[h('small',{class:'lbl'},'未收 '),money(c.out,1e6)]),
      h('span',{class:'ds'},
        h('span',{class:'due'},dueText(it,c,today)),
        h('span',{class:'inv'+(it.invoiced?' yes':'')},it.invoiced?'已开票':'未开票')),
      h('span',{class:'pg'},'已收 '+money(c.paid,1e6)+' / '+money(c.amount,1e6)),
      bar);
  }

  function listView(){
    const rows=sortItems(items,today);
    const open=rows.filter(r=>r.c.st!=='paid');
    const sum=(arr,f)=>r2(arr.reduce((a,r)=>a+f(r),0));
    const od=open.filter(r=>r.c.st==='overdue');
    const sn=open.filter(r=>r.c.st==='soon');
    const lim=size==='3x3'?10000:1000000;
    const f=ui.filter;
    const shown=rows.filter(r=>f==='open'?r.c.st!=='paid':f==='done'?r.c.st==='paid':true);
    const stat=(cls,k,v)=>h('div',{class:'stat '+cls},h('div',{class:'k'},k),h('div',{class:'v'},v));
    const stats=h('div',{class:'stats'},
      stat('s-out','待收',money(sum(open,r=>r.c.out),lim)),
      stat('s-od'+(od.length?' hot':''),'逾期'+(od.length?' '+od.length+'笔':''),money(sum(od,r=>r.c.out),lim)),
      stat('s-soon','7天内',money(sum(sn,r=>r.c.out),lim)),
      stat('s-paid','已收',money(sum(rows,r=>r.c.paid),lim)));
    const cnt={all:rows.length,open:open.length,done:rows.length-open.length};
    const tabs=h('div',{class:'tabs'},[['all','全部'],['open','未收齐'],['done','已收齐']].map(t=>
      h('button',{type:'button',class:'tab'+(f===t[0]?' on':''),'aria-pressed':f===t[0]?'true':'false',
        onclick:()=>{ui.filter=t[0];redraw();}},t[1]+' '+cnt[t[0]])));
    const list=h('div',{class:'list'},shown.length?shown.map(rowEl):
      h('div',{class:'empty'},rows.length?'这个分类下没有记录':'还没有应收记录。点「新增」记下第一笔。'));
    const add=btn('pri addbtn','＋ 新增',()=>{
      ui.draft={client:'',project:'',amount:'',due:'',invoiced:false};
      ui.view='form';ui.err='';redraw();
    },{'aria-label':'新增应收'});
    return h('div',{class:'lv'},stats,add,h('div',{class:'main'},tabs,list));
  }


  /* ---------- 详情：收款记录 ---------- */
  function goList(){
    ui.view='list';ui.sel=null;ui.pay=null;ui.err='';ui.delPay=null;ui.delItem=false;redraw();
  }

  function payRow(it,p){
    const ask=ui.delPay===p.id;
    return h('div',{class:'pay'},
      h('span',{class:'pd'},showDate(p.date,today)),
      h('span',{class:'pa'},money(p.amount)),
      ask?[
        btn('sm danger','确认删除',()=>{
          ui.delPay=null;
          Promise.resolve(update(s=>mapItem(s,it.id,x=>Object.assign({},x,{payments:(x.payments||[]).filter(q=>q.id!==p.id)})))).catch(fail);
        }),
        btn('sm','取消',()=>{ui.delPay=null;redraw();})
      ]:h('button',{type:'button',class:'x','aria-label':'删除这笔收款',onclick:()=>{ui.delPay=p.id;redraw();}},'×'));
  }

  function submitPay(it,c,pay){
    if(ui.busy)return;
    const amt=parseAmt(pay.amount);
    if(!(amt>0))return warn('请填写本次收款金额（大于 0）');
    if(!validDate(pay.date))return warn('请选择收款日期');
    if(amt>c.out+0.001)return warn('本次金额超过未收的 '+money(c.out)+'。如有增项，请先在「编辑」里调整约定金额');
    const rec={id:uid(),date:pay.date,amount:amt};
    ui.busy=true;
    Promise.resolve(commit(s=>mapItem(s,it.id,x=>Object.assign({},x,{payments:(x.payments||[]).concat([rec]).sort(byDate)})),
      nu({pay:null}))).catch(fail);
  }

  function payForm(it,c){
    const pay=ui.pay||(ui.pay={date:today,amount:''});
    const dateIn=h('input',{class:'in',type:'date',value:pay.date,'aria-label':'收款日期',oninput:e=>{pay.date=e.target.value;}});
    const amtIn=h('input',{class:'in',type:'number',step:'any',inputmode:'decimal',placeholder:'未收 '+money(c.out),value:pay.amount,
      'aria-label':'本次收款金额（元）',oninput:e=>{pay.amount=e.target.value;},
      onkeydown:e=>{if(e.key==='Enter')submitPay(it,c,pay);}});
    return h('div',{class:'sec'},
      h('div',{class:'sh'},'记一笔收款'),
      h('div',{class:'pform'},
        h('label',{class:'fld'},h('span',{class:'fl'},'收款日期'),dateIn),
        h('label',{class:'fld'},h('span',{class:'fl'},'本次收到（元）'),amtIn)),
      h('div',{class:'acts'},
        btn('sm','填入全部未收',()=>{pay.amount=String(c.out);redraw();}),
        btn('pri','记下这笔',()=>submitPay(it,c,pay))));
  }

  /* ---------- 详情 ---------- */
  function detailView(it){
    const c=calc(it,today);
    const pays=(it.payments||[]).slice().sort(byDate);
    const cell=(k,v,cls)=>h('div',{class:'sc '+(cls||'')},h('span',{class:'k'},k),h('span',{class:'v'},v));
